package cn.mop.persistence;
import cn.mop.domain.DomainException;
import cn.mop.domain.backup.BackupRunState;
import cn.mop.domain.backup.BackupRunState.*;
import org.junit.jupiter.api.Test;
import java.io.*;import java.time.*;import java.util.*;import java.security.*;
import static org.junit.jupiter.api.Assertions.*;
class BackupRunSnapshotCodecTest {
 final BackupRunSnapshotCodec codec=new BackupRunSnapshotCodec();
 final UUID run=UUID.fromString("75000000-0000-4000-8000-000000000001"),tenant=UUID.fromString("75000000-0000-4000-8000-000000000002"),asset=UUID.fromString("75000000-0000-4000-8000-000000000003");final Instant at=Instant.parse("2026-10-21T00:00:00Z");
 BackupRunState queued(){return BackupRunState.queued(tenant,asset,at);}
 static String hash(byte[] b)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b));}
 BackupRunState decode(byte[] b)throws Exception{return codec.decode(b,hash(b),run,tenant,asset);}
 @Test void allOutcomesRoundTripWithDeterministicPayloadAndHash(){var r=queued().start(0,at);var failure=r.fail(1,at,Failure.STORAGE_FAILED);var success=r.succeed(1,at,new StoredVersion(tenant,asset,UUID.randomUUID(),"b".repeat(64),10,at));for(var state:List.of(queued(),r,r.markUnknown(1,at),failure,success)){var a=codec.encode(run,state);var b=codec.encode(run,state);assertArrayEquals(a.bytes(),b.bytes());assertEquals(a.sha256(),b.sha256());assertEquals(state.snapshot(),codec.decode(a.bytes(),a.sha256(),run,tenant,asset).snapshot());assertTrue(a.bytes().length<BackupRunSnapshotCodec.MAX_BYTES);}}
 @Test void runIdentityParticipatesInPayloadAndExpectedScope(){var doc=codec.encode(run,queued());assertNotEquals(doc.sha256(),codec.encode(UUID.randomUUID(),queued()).sha256());assertThrows(DomainException.class,()->codec.decode(doc.bytes(),doc.sha256(),UUID.randomUUID(),tenant,asset));assertThrows(DomainException.class,()->codec.decode(doc.bytes(),doc.sha256(),run,UUID.randomUUID(),asset));assertThrows(DomainException.class,()->codec.decode(doc.bytes(),doc.sha256(),run,tenant,UUID.randomUUID()));}
 @Test void modifiedBytesAndExpectedHashAreRejected(){var doc=codec.encode(run,queued());var b=doc.bytes();b[b.length-1]^=1;assertThrows(DomainException.class,()->codec.decode(b,doc.sha256(),run,tenant,asset));assertThrows(DomainException.class,()->codec.decode(doc.bytes(),"0".repeat(64),run,tenant,asset));assertThrows(DomainException.class,()->codec.decode(doc.bytes(),doc.sha256().toUpperCase(Locale.ROOT),run,tenant,asset));}
 @Test void truncatedAndTrailingDataRejectEvenWithMatchingHash()throws Exception{byte[] bytes=codec.encode(run,queued()).bytes();for(int i=0;i<bytes.length;i++){var b=Arrays.copyOf(bytes,i);assertThrows(DomainException.class,()->decode(b));}assertThrows(DomainException.class,()->decode(Arrays.copyOf(bytes,bytes.length+1)));}
 @Test void oversizeNullAndMissingIdentityReject(){assertThrows(DomainException.class,()->codec.decode(new byte[4097],"0".repeat(64),run,tenant,asset));assertThrows(DomainException.class,()->codec.decode(null,null,run,tenant,asset));assertThrows(DomainException.class,()->codec.encode(null,queued()));assertThrows(DomainException.class,()->codec.encode(run,null));var d=codec.encode(run,queued());assertThrows(DomainException.class,()->codec.decode(d.bytes(),d.sha256(),null,tenant,asset));}
 @Test void documentBytesAreDetachedAndItsConstructorChecksDigest()throws Exception{var doc=codec.encode(run,queued());var bytes=doc.bytes();bytes[0]^=1;assertNotEquals(bytes[0],doc.bytes()[0]);assertThrows(DomainException.class,()->new BackupRunSnapshotCodec.Document(bytes,doc.sha256()));var original=doc.bytes();var copy=new BackupRunSnapshotCodec.Document(original,hash(original));original[0]^=1;assertArrayEquals(doc.bytes(),copy.bytes());}
 byte[] manual(String runText,long version,int count,boolean noncanonicalBoolean)throws Exception{try(var bytes=new ByteArrayOutputStream();var out=new DataOutputStream(bytes)){out.writeUTF(BackupRunSnapshotCodec.FORMAT);out.writeUTF(runText);out.writeUTF(tenant.toString());out.writeUTF(asset.toString());out.writeLong(at.toEpochMilli());out.writeLong(version);out.writeInt(count);if(count==1){out.writeInt(1);out.writeLong(at.toEpochMilli());out.writeLong(at.toEpochMilli());out.writeByte(noncanonicalBoolean?2:1);out.writeLong(at.toEpochMilli());out.writeUTF("FAILED");out.writeBoolean(true);out.writeUTF("STORAGE_FAILED");out.writeBoolean(false);}out.flush();return bytes.toByteArray();}}
 @Test void canonicalBooleanAndUuidEncodingAreEnforced()throws Exception{assertEquals(State.RETRY_WAIT,decode(manual(run.toString(),2,1,false)).state());assertThrows(DomainException.class,()->decode(manual(run.toString(),2,1,true)));assertThrows(DomainException.class,()->decode(manual("75000000-0-4000-8000-1",2,1,false)));}
 @Test void malformedLogicalVersionsAndCountsAreNotAcceptedAsTrustedHashes(){assertThrows(DomainException.class,()->decode(manual(run.toString(),1,1,false)));assertThrows(DomainException.class,()->decode(manual(run.toString(),0,-1,false)));assertThrows(DomainException.class,()->decode(manual(run.toString(),8,4,false)));}
 @Test void unknownResultSurvivesDecodingWithoutEnablingAnotherAttempt(){var s=queued().start(0,at).markUnknown(1,at.plusSeconds(1));var d=codec.encode(run,s);var restored=codec.decode(d.bytes(),d.sha256(),run,tenant,asset);assertTrue(restored.reconciliationRequired());assertNull(restored.nextAttemptAt());assertThrows(DomainException.class,()->restored.start(restored.version(),at.plusSeconds(10000)));assertFalse(restored.automaticTicketAllowed());}
 @Test void corruptionReportsOnlySafeStorageError(){var e=assertThrows(DomainException.class,()->codec.decode("PRIVATE_UNTRUSTED_SNAPSHOT".getBytes(),"0".repeat(64),run,tenant,asset));assertEquals(503,e.status);assertEquals("BACKUP_RUN_SNAPSHOT_INVALID",e.code);assertFalse(e.getMessage().contains("PRIVATE_UNTRUSTED_SNAPSHOT"));assertNull(e.getCause());}
 @Test void independentlyEncodedQueuedGoldenVectorIsStable(){byte[] expected=Base64.getDecoder().decode("ABpNT1BfQkFDS1VQX1JVTl9TTkFQU0hPVF9WMQAkNzUwMDAwMDAtMDAwMC00MDAwLTgwMDAtMDAwMDAwMDAwMDAxACQ3NTAwMDAwMC0wMDAwLTQwMDAtODAwMC0wMDAwMDAwMDAwMDIAJDc1MDAwMDAwLTAwMDAtNDAwMC04MDAwLTAwMDAwMDAwMDAwMwAAAaFbwfQAAAAAAAAAAAAAAAAA");var document=codec.encode(run,queued());assertArrayEquals(expected,document.bytes());assertEquals("3c1123f1a2715e839a69f0711ba57b32a4c55b34ccde4bc0a9e8b9159a4400f6",document.sha256());assertEquals(queued().snapshot(),codec.decode(expected,"3c1123f1a2715e839a69f0711ba57b32a4c55b34ccde4bc0a9e8b9159a4400f6",run,tenant,asset).snapshot());}

}
